'use strict';
var ControlCorteDxfGeometry = (()=>{
 const clone=v=>JSON.parse(JSON.stringify(v)), eps=1e-7, dist=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]), cross=(a,b)=>a[0]*b[1]-a[1]*b[0], sub=(a,b)=>[a[0]-b[0],a[1]-b[1]], lerp=(a,b,t)=>a.map((v,i)=>v+(b[i]-v)*t);
 function validate(d){if(!d||d.version!==1||!Array.isArray(d.entities)||d.entities.length>2000)throw Error('Desenho inválido.');const ids=new Set();for(const e of d.entities){if(!/^D\d+$/.test(e.id)||ids.has(e.id)||!['macho','femea','canal','vinco','construcao'].includes(e.op)||!Array.isArray(e.points)||e.points.length<2||e.points.length>10000||e.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(n=>!Number.isFinite(n)||Math.abs(n)>30000)))throw Error('Entidade inválida.');ids.add(e.id);if(e.closed&&e.points.length<3)throw Error('Contorno fechado inválido.');}return clone(d);}
 function circle(x,y,r){if(!(r>0))throw Error('Informe raio positivo.');const n=Math.min(4096,Math.max(48,Math.ceil(Math.PI/Math.acos(Math.max(-1,1-.01/r)))));return Array.from({length:n},(_,i)=>[x+r*Math.cos(i*2*Math.PI/n),y+r*Math.sin(i*2*Math.PI/n)]);}
 function intersection(a,b,c,d){const v=sub(b,a),w=sub(d,c),den=cross(v,w);if(Math.abs(den)<eps)return null;const t=cross(sub(c,a),w)/den,u=cross(sub(c,a),v)/den;return t>=-eps&&t<=1+eps&&u>=-eps&&u<=1+eps?{t,u,point:lerp(a,b,t)}:null;}
 function nearest(e,p){let best=null;const n=e.points.length-(e.closed?0:1);for(let i=0;i<n;i++){const a=e.points[i],b=e.points[(i+1)%e.points.length],v=sub(b,a),l=v[0]**2+v[1]**2,t=l?Math.max(0,Math.min(1,((p[0]-a[0])*v[0]+(p[1]-a[1])*v[1])/l)):0,q=lerp(a,b,t),distance=dist(p,q);if(!best||distance<best.distance)best={i,t,point:q,distance};}return best;}
 // Remove only the portion picked, bounded by actual intersections. Result is open.
 function inside(p,ring){let yes=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes;}return yes||nearest({points:ring,closed:true},p).distance<eps;}
 function simple(e){const p=e.points,n=p.length;for(let i=0;i<n-(e.closed?0:1);i++){if(dist(p[i],p[(i+1)%n])<eps)throw Error('Há segmento de comprimento zero.');for(let j=i+2;j<n-(e.closed?0:1);j++){if(e.closed&&i===0&&j===n-1)continue;if(intersection(p[i],p[(i+1)%n],p[j],p[(j+1)%n]))throw Error('Contorno cruza a si próprio.');}}}
 function part(d,options){validate(d);const active=d.entities.filter(e=>e.op!=='construcao'),outer=active.filter(e=>e.op==='macho');if(outer.length!==1||!outer[0].closed)throw Error('Defina exatamente um contorno MACHO fechado por peça.');active.forEach(simple);const outline=outer[0].points,min=[0,1].map(i=>Math.min(...outline.map(p=>p[i]))),max=[0,1].map(i=>Math.max(...outline.map(p=>p[i]))),map=p=>p.map((v,i)=>v-min[i]),t=Number(options.t);if(!(t>0&&t<30000))throw Error('Espessura inválida.');for(const e of active)if(e.depth!==undefined&&(!Number.isFinite(e.depth)||e.depth<=0||e.depth>t))throw Error('Profundidade Z deve ficar entre zero e a espessura da chapa.');const result={id:'STEP1',name:String(options.name||'Peça desenhada').slice(0,240),kind:'flat',w:max[0]-min[0],h:max[1]-min[1],t,outline:outline.map(map),holes:[],channels:[],folds:[],grooves:[],panels:[],qty:Number(options.qty),selected:true,...(outer[0].depth!==undefined?{outerDepth:outer[0].depth}:{})};
 for(const e of active.filter(e=>e!==outer[0])){if(!e.points.every(p=>inside(p,outline)))throw Error('Operação fora do contorno externo.');for(let i=1;i<e.points.length;i++)if(!inside(lerp(e.points[i-1],e.points[i],.5),outline))throw Error('Operação atravessa o exterior da peça.');const points=e.points.map(map);if(e.op==='vinco'){result.grooves.push(points);result.grooveDepths??=[];result.grooveDepths.push(e.depth??t-1.5);continue;}if(!e.closed)throw Error('Fêmea e canal precisam de contorno fechado. Use Unir / fechar.');if(e.op==='femea')result.holes.push({panel:0,points,circle:e.circle?{x:e.circle.x-min[0],y:e.circle.y-min[1],radius:e.circle.radius}:null,...(e.depth!==undefined?{depth:e.depth}:{})});if(e.op==='canal'){const depth=Number(e.depth);if(!(depth>0&&depth<=t))throw Error('Profundidade do canal deve ficar entre zero e a espessura.');result.channels.push({x0:Math.min(...points.map(p=>p[0])),x1:Math.max(...points.map(p=>p[0])),y0:Math.min(...points.map(p=>p[1])),y1:Math.max(...points.map(p=>p[1])),depth,points,pocket:true,panel:0});}}
 const inner=active.filter(e=>e!==outer[0]&&e.closed);for(const e of active.filter(e=>e!==outer[0]))for(let i=0;i<e.points.length-(e.closed?0:1);i++){const a=e.points[i],b=e.points[(i+1)%e.points.length];for(let j=0;j<outline.length;j++){const hit=intersection(a,b,outline[j],outline[(j+1)%outline.length]);if(hit&&hit.t>eps&&hit.t<1-eps)throw Error('Operação cruza o contorno externo.');}}for(let i=0;i<inner.length;i++)for(let j=i+1;j<inner.length;j++){const a=inner[i],b=inner[j];if(a.points.some(p=>inside(p,b.points))||b.points.some(p=>inside(p,a.points))||a.points.some((p,k)=>b.points.some((q,l)=>intersection(p,a.points[(k+1)%a.points.length],q,b.points[(l+1)%b.points.length]))))throw Error('Operações internas sobrepostas: separe os contornos.');}return result;}
 return {validate,circle,intersection,nearest,inside,simple,part};
})();

